import React from 'react';
import { BrowserRouter, Routes, Route, Navigate } from 'react-router-dom';
import { Toaster } from 'react-hot-toast';
import { AuthProvider, useAuth } from './context/AuthContext';
import KibaReminder from './components/KibaReminder';
import Login from './pages/Login';
import Register from './pages/Register';
import ForgotPassword from './pages/ForgotPassword';
import CustomerDashboard from './pages/CustomerDashboard';
import GiveConsent from './pages/GiveConsent';
import AccessLogs from './pages/AccessLogs';
import StaffDashboard from './pages/StaffDashboard';
import AdminDashboard from './pages/AdminDashboard';
import KibaChat from './pages/KibaChat';
import LandingPage from './pages/LandingPage';
import JobDetail from './pages/JobDetail';
import ApplyJob from './pages/ApplyJob';
import TalentPool from './pages/TalentPool';
import ThirdPartyView from './pages/ThirdPartyView';

const ProtectedRoute = ({ children, roles }) => {
  const { user, loading } = useAuth();
  if (loading) return (
    <div style={{ display: 'flex', justifyContent: 'center', alignItems: 'center', height: '100vh', fontSize: 16, color: '#0EA5E9', fontFamily: 'Inter, sans-serif' }}>
      Loading KibaliGuard...
    </div>
  );
  if (!user) return <Navigate to="/login" />;
  if (roles && !roles.includes(user.role)) return <Navigate to="/login" />;
  return children;
};

const AppRoutes = () => {
  const { user } = useAuth();
  return (
    <Routes>
      <Route path="/" element={<LandingPage />} />
      <Route path="/login" element={!user ? <Login /> : <Navigate to={user.role === 'admin' ? '/admin' : user.role === 'staff' ? '/staff' : '/dashboard'} />} />
      <Route path="/register" element={!user ? <Register /> : <Navigate to="/dashboard" />} />
      <Route path="/forgot-password" element={<ForgotPassword />} />
      <Route path="/jobs/:id" element={<JobDetail />} />
      <Route path="/third-party/:applicationId/:requestId/:token" element={<ThirdPartyView />} />
      <Route path="/dashboard" element={<ProtectedRoute roles={['customer']}><CustomerDashboard /></ProtectedRoute>} />
      <Route path="/give-consent" element={<ProtectedRoute roles={['customer']}><GiveConsent /></ProtectedRoute>} />
      <Route path="/access-logs" element={<ProtectedRoute roles={['customer']}><AccessLogs /></ProtectedRoute>} />
      <Route path="/apply/:jobId" element={<ProtectedRoute roles={['customer']}><ApplyJob /></ProtectedRoute>} />
      <Route path="/talent-pool" element={<ProtectedRoute roles={['customer']}><TalentPool /></ProtectedRoute>} />
      <Route path="/staff" element={<ProtectedRoute roles={['staff', 'admin']}><StaffDashboard /></ProtectedRoute>} />
      <Route path="/admin" element={<ProtectedRoute roles={['admin']}><AdminDashboard /></ProtectedRoute>} />
      <Route path="/chat" element={<ProtectedRoute roles={['customer']}><KibaChat /></ProtectedRoute>} />
      <Route path="*" element={<Navigate to="/" />} />
    </Routes>
  );
};

function App() {
  return (
    <AuthProvider>
      <BrowserRouter>
        <Toaster position="top-right" toastOptions={{ duration: 4000, style: { fontFamily: 'Inter, sans-serif', borderRadius: '12px', fontWeight: 500 } }} />
        <AppRoutes />
        <KibaReminder />
      </BrowserRouter>
    </AuthProvider>
  );
}

export default App;
